with q as (select * from (values
('pcac-lc129-prescription-09','LC nº 129/2004 — prescrição','Qual é o prazo prescricional da falta disciplinar sujeita à pena de advertência, conforme o art. 118 da LC nº 129/2004?','(A) 30 dias.\n(B) 6 meses.\n(C) 1 ano.\n(D) 2 anos.\n(E) 5 anos.','B','O art. 118, I, fixa seis meses para falta sujeita à advertência.'),
('pcac-lc129-suspension-prescription-10','LC nº 129/2004 — prescrição','O prazo prescricional da falta sujeita à suspensão é de:','(A) 6 meses.\n(B) 1 ano.\n(C) 2 anos.\n(D) 4 anos.\n(E) 5 anos.','C','O art. 118, II, estabelece dois anos para falta sujeita à suspensão.'),
('pcac-lc129-syndicance-30days-11','LC nº 129/2004 — sindicância','Segundo a redação do art. 127, a sindicância deverá ser concluída em:','(A) 10 dias improrrogáveis.\n(B) 15 dias.\n(C) 20 dias.\n(D) 30 dias, prorrogáveis mediante solicitação fundamentada.\n(E) 90 dias.','D','O art. 127 prevê 30 dias, contados da portaria inaugural ou do auto de constatação, com possibilidade de prorrogação fundamentada.'),
('pcac-lc129-responsibility-12','LC nº 129/2004 — responsabilidade','Conforme o art. 106-C da LC nº 129/2004, as sanções civis, penais e administrativas:','(A) São necessariamente excludentes.\n(B) Não podem ser aplicadas pelo mesmo fato.\n(C) Podem cumular-se e são independentes entre si.\n(D) Dependem sempre de condenação criminal prévia.\n(E) São absorvidas pela sanção administrativa.','C','O art. 106-C prevê a possibilidade de cumulação e independência entre as esferas civil, penal e administrativa.'),
('pcac-lc129-review-13','LC nº 129/2004 — revisão do PAD','É hipótese legal para revisão do processo disciplinar:','(A) Simples inconformismo sem fundamento.\n(B) Surgimento, após a decisão, de prova da inocência do punido.\n(C) Pedido anônimo sem elementos.\n(D) Discordância abstrata com a autoridade.\n(E) Ausência de advogado em qualquer fase, automaticamente.','B','O art. 157, IV, admite revisão quando surgir, após a decisão, prova da inocência do punido.'),
('pcac-lc526-resignation-training-14','LC nº 526/2026 — ressarcimento de formação','O policial civil que pede exoneração antes de completar três anos de efetivo exercício:','(A) Deve devolver todos os vencimentos recebidos.\n(B) Nunca ressarce despesas.\n(C) Ressarce proporcionalmente despesas diretas e individualizadas de custeio da formação, ressalvada a hipótese legal de saúde incapacitante.\n(D) Paga multa fixa de 50% da remuneração.\n(E) Ressarce apenas se for demitido.','C','O art. 79-B, §§ 4º e 5º, prevê ressarcimento proporcional de despesas diretas e individualizadas, vedada a inclusão de vencimentos e parcelas remuneratórias; há exceção por motivo de saúde incapacitante comprovado.'),
('pcac-lc526-five-year-stay-15','LC nº 526/2026 — lotação inicial','Após entrar em exercício na unidade de primeira lotação, qual é o período mínimo de permanência no município previsto no art. 67, § 14?','(A) 2 anos.\n(B) 3 anos.\n(C) 4 anos.\n(D) 5 anos de efetivo exercício.\n(E) 10 anos.','D','O art. 67, § 14, estabelece permanência mínima de cinco anos de efetivo exercício no município da lotação inicial, com vedação de movimentações especificadas.'),
('pcac-lc526-firearms-training-16','LC nº 526/2026 — porte de arma no curso','Durante o curso específico de formação policial, qual regra se aplica ao porte ou condução de arma de fogo?','(A) É livre em todas as dependências.\n(B) É vedado nas salas de aula e dependências administrativas, ressalvadas atividades práticas de armamento e tiro no espaço e tempo necessários.\n(C) É obrigatório durante todo o internato.\n(D) É permitido apenas para alunos com maior nota.\n(E) A autorização definitiva é concedida antes do curso.','B','O art. 79-A, §§ 4º e 5º, veda porte/condução nas áreas indicadas durante o curso, com exceção restrita às práticas; a autorização individual definitiva só vem após conclusão e aprovação.')
) as t(external_item_key,subtopic,question_text,options_text,answer,explanation))
insert into public.curated_question_catalog
(source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,question_text,official_answer,explanation,difficulty,content_status,is_original,state,career_category,role_type,tested_topic,import_content_key,import_unique_key,didactic_provenance)
select '43712f0d-aad2-48b5-a685-6937551f2d74','d204d14f-8aa6-4c57-92ad-3fb3c3e901f1',external_item_key,'Norte Concursos — treino autoral PC-AC 2026',2026,'Oficial Investigador de Polícia','AUTORAL','Legislação Institucional',subtopic,question_text||E'\n\n'||options_text,answer,explanation,'média','active',true,'AC','Polícia Civil','Oficial Investigador de Polícia',subtopic,external_item_key,'pcac-2026-'||external_item_key,jsonb_build_object('kind','didactic_original','authored',true,'target_exam','PC-AC 2026 — Oficial Investigador de Polícia','not_official_exam',true,'license_note','Questão autoral inédita; não é item oficial da IDECAN','linked_study_material_slug','pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','source_material_slug','pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','source_exam_reference','Edital nº 001 SEAD/PCAC, de 05/11/2026, Anexo III') from q
